// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2020, "10-11", [{"author":"А. Сомин","question":"Полностью наш конкурс называется «Русский медвежонок — языкознание для всех». А как иначе можно назвать языкознание?","choices":["<em>лингвинистика</em>","<em>леньгвистика</em>","<em>ленгвистика</em>","<em>лингвистика</em>","<em>лингвисьтика</em>."],"key":"Г","review":["Другое название науки","Языкознание изучает устройство, употребление и историю языков. В названиях из списка правильно написано только одно слово.","Наука о языке называется «лингвистика». Вторая часть пишется «-гвистика», без лишних букв."]},{"author":"М. Рубинштейн","question":"В какой паре соотношение между глаголами не такое, как в остальных?","choices":["<em>договорить</em> — <em>договаривать</em>","<em>подговорить</em> — <em>подговаривать</em>","<em>обговорить</em> — <em>обговаривать</em>","<em>разговорить</em> — <em>разговаривать</em>","<em>уговорить</em> — <em>уговаривать</em>."],"key":"Г","review":["Проверка видовых пар","В парах «договорить — договаривать», «подговорить — подговаривать», «обговорить — обговаривать» и «уговорить — уговаривать» сохраняется содержание действия.","«Разговорить» значит расшевелить собеседника, чтобы он начал говорить. «Разговаривать» значит вести разговор. Это разные действия."]},{"author":"Б. Иомдин","question":"Что может быть глаголом?","choices":["<em>эльф</em>","<em>тролль</em>","<em>гном</em>","<em>гоблин</em>","<em>ведьма</em>."],"key":"Б","review":["Название существа и глагол","У слов из списка привычное значение — сказочные существа. Проверь, какое написание можно использовать как приказ.","«Тролль» — повелительная форма глагола «троллить», например «не тролль собеседника». Написание совпадает с названием существа."]},{"author":"И. Рубанов","question":"В каком из этих словосочетаний слово <em>корни</em> обычно имеет иной смысл, чем в остальных?","choices":["<em>боковые корни</em>","<em>квадратные корни</em>","<em>круглые корни</em>","<em>стержневые корни</em>","<em>толстые корни</em>."],"key":"Б","review":["Два значения «корни»","Боковые, круглые, стержневые и толстые корни могут быть частями растений. Слова описывают их форму и положение.","«Квадратный корень» — математический термин. Он не описывает форму растительного корня."]},{"author":"И. Рубанов","question":"В каждое из слов <em>покинуть</em>, <em>поколоть</em>, <em>положить</em>, <em>посчитать</em>, <em>пошить</em> после второй буквы вписали букву <em>д</em>. Какое из них в одном из своих значений после этого сохранило первоначальный смысл?","choices":["<em>покинуть</em>","<em>поколоть</em>","<em>положить</em>","<em>посчитать</em>","<em>пошить</em>."],"key":"Г","review":["Одна добавленная буква","Получаем «подкинуть», «подколоть», «подложить», «подсчитать», «подшить». Сравни новые и исходные действия.","«Подсчитать расходы» можно заменить на «посчитать расходы». В остальных парах добавление Д вносит новое значение."]},{"author":"Б. Иомдин","question":"Дан конец заголовка новостного сообщения: … <em>угрожал авокадо при ограблении почты.</em> В каком падеже здесь стоит слово <em>авокадо</em>?","choices":["в именительном","в родительном","в дательном","в винительном","в творительном."],"key":"Д","review":["Авокадо в новости","Представь, что вместо «авокадо» в заголовке написано название другого предмета. При ограблении им могли угрожать как оружием.","Получается вопрос «угрожал чем?». Это творительный падеж, хотя у несклоняемого слова написание не меняется."]},{"author":"Е. Бикмаев","question":"Какое из этих слов родственно глаголу <em>подозревать</em>?","choices":["<em>вызревать</em>","<em>назревать</em>","<em>перезревать</em>","<em>прозревать</em>","<em>созревать</em>."],"key":"Г","review":["Два значения корня «зре-»","«Вызревать», «назревать», «перезревать» и «созревать» связаны со зрелостью и развитием. В них узнаётся «зреть» в смысле «становиться зрелым».","«Подозревать» и «прозревать» исторически связаны с другим «зреть» — «видеть». Из вариантов подходит «прозревать»."]},{"author":"П. Аркадьев","question":"<em>Она поёт в церковных хорах\nИ в монастырских вечерах\nИ, рассыпая в урны прах,\nПечатает вино в амфорах.</em>\nКакое слово в этом четверостишии Осипа Мандельштама произносится не так, как предписывает современная литературная норма?","choices":["<em>хорах</em>","<em>вечерах</em>","<em>рассыпая</em>","<em>амфорах</em>","все слова произносятся в соответствии с современной литературной нормой."],"key":"Г","review":["Рифма и ударение","В четверостишии «хорах» рифмуется с «амфорах». Чтобы рифма получилась, ударение в обоих словах должно стоять на О.","У «а́мфоры» в современной норме ударение на первом слоге, и формы его сохраняют. Поэт произносит «амфо́рах», что отличается от нормы."]},{"author":"Б. Иомдин","question":"В каком примере <em>закончить книгу</em> значит не то, что в остальных?","choices":["<em>На этом я закончу книгу. Приношу извинения за литературный слог и избыток медицины</em>. (Н. М. Амосов)","<em>К этому времени Мандельштам закончил книгу стихов</em>. (Э. Г. Герштейн)","<em>Я только что закончил книгу Говарда Фаста «Голый бог»</em>. (В. П. Некрасов)","<em>Война помешала мне закончить книгу «Двенадцать портретов», над которой я возился последние годы</em>. (К. И. Чуковский)","<em>А ведь я должен закончить книгу, над которой работал 7 лет</em>. (М. М. Зощенко)"],"key":"В","review":["Что делают с книгой","В четырёх примерах авторы или составители завершают работу над собственной книгой.","Говард Фаст — автор книги, которую Некрасов закончил читать. Значит, в его фразе выражение имеет другой смысл."]},{"author":"М. Рубинштейн","question":"Одна из глав в книге о фотографировании называется «Навести X — не Х». Какое слово мы заменили на Х?","choices":["<em>вспышка</em>","<em>порядок</em>","<em>резкость</em>","<em>фокус</em>","<em>фото</em>."],"key":"Г","review":["Слово из фотографии","«Навести» при съёмке значит сделать объект чётким на фотографии. Ищи слово, которое одновременно может обозначать трюк.","В фотографии говорят о фокусе, а в представлении «фокус» означает трюк. Поэтому глава называется «Навести фокус — не фокус»."]},{"author":"С. Дьяченко","question":"Какое из этих слов в архангельских говорах имеет значение ‘толстый, упитанный’?","choices":["<em>вечкотливый</em>","<em>пылкий</em>","<em>томный</em>","<em>добрый</em>","<em>злой</em>."],"key":"Г","review":["Архангельский говор","«Добрым» можно назвать не только человека с хорошим характером. Сравни выражение «добрый кусок»: это большой, основательный кусок.","В архангельских говорах «добрый» может обозначать упитанного, полного человека. Из списка подходит это прилагательное."]},{"author":"Е. Бикмаев","question":"Даны латинские названия пяти видов клюквы (по устаревшей классификации): <em>Oxycoccus erythrocarpus</em>, <em>Oxycoccus quadripetalus</em>, <em>Oxycoccus macrocarpus</em>, <em>Oxycoccus palustris</em>, <em>Oxycoccus microcarpus.</em> Первое слово в названиях обозначает клюкву. Выберите вариант, где даны в правильном порядке переводы вторых слов.","choices":["<em>красноплодная</em>, <em>четырёхлепестная</em>, <em>мелкоплодная</em>, <em>луговая</em>, <em>крупноплодная</em>","<em>красноплодная</em>, <em>четырёхлепестная</em>, <em>крупноплодная</em>, <em>болотная</em>, <em>мелкоплодная</em>","<em>красносортная</em>, <em>четырёхлепестная</em>, <em>крупноплодная</em>, <em>садовая</em>, <em>мелкоплодная</em>","<em>черносортная</em>, <em>пятилепестная</em>, <em>малоплодная</em>, <em>болотная</em>, <em>бесплодная</em>","<em>черноплодная</em>, <em>пятилепестная</em>, <em>крупноплодная</em>, <em>луговая</em>, <em>мелкоплодная</em>."],"key":"Б","review":["Названия видов клюквы","Сравни части слов: «macro-» значит крупный, «micro-» — мелкий, «-carpus» относится к плоду. «Quadri-» означает четыре, «-petalus» — лепесток.","«Erythro-» обозначает красный цвет, а «palustris» — болотное местообитание. Получается красноплодная, четырёхлепестная, крупноплодная, болотная, мелкоплодная."]},{"author":"С. Переверзева","question":"В каком случае скобки следует раскрыть иначе, чем в остальных?","choices":["…<em>Секрет этой бесконечности ― только в(не)возможности достигнуть цели, то есть конца</em>. (М. Ю. Лермонтов)","…<em>Надо понять, что ежели мы будем разбрасываться, как это, к сожалению, до сих пор было, то сам тайный советник Кузьма Прутков окажется в(не)возможности поддержать нас</em>. (М. Е. Салтыков-Щедрин)","<em>Переменились ли Иоанновы мысли: уверился ли он в(не)возможности господствовать над Польшею и Литвою, как бы ему хотелось?</em> (Н. М. Карамзин)","<em>Беда не в отсутствии у нас оперативных планов, а в(не)возможности их выполнить в той обстановке, которая сложилась</em>. (К. М. Симонов)","<em>― Необходимая перестройка наших защитных реакций произойдет вряд ли раньше, чем через два месяца, ― заявила Эвиза Танет таким тоном, как будто она была виновата в(не)возможности провести иммунизацию скорее</em>. (И. А. Ефремов)"],"key":"Б","review":["Слитно или с предлогом","В большинстве цитат речь о невозможности сделать что-либо. «Невозможность» — одно существительное, перед ним пишем отдельное «в».","В цитате о Пруткове получается «вне возможности поддержать нас», то есть за пределами возможности. «Вне» — отдельный предлог, а «возможность» написана без НЕ."]},{"author":"М. Рубинштейн","question":"Историк Н. И. Костомаров, живший в XIX веке, писал, что древние славяне умели «делать ладьи и рыболовные снасти, возделывать землю, ____ домашних животных». Какое слово пропущено в этом отрывке?","choices":["<em>возить</em>","<em>увозить</em>","<em>водить</em>","<em>уводить</em>","<em>отводить</em>."],"key":"В","review":["Животные у славян","Костомаров перечисляет постоянные занятия: строить ладьи, ловить рыбу, обрабатывать землю. С животными нужно выбрать такой же вид хозяйства.","В старой речи «водить животных» значило держать и разводить их. Поэтому подходит «водить»."]},{"author":"А. Малышева","question":"В каком из этих сложных слов корни соотносятся между собой не так, как в остальных?","choices":["<em>землепашец</em>","<em>мореход</em>","<em>рыболов</em>","<em>полководец</em>","<em>золотоискатель</em>."],"key":"Б","review":["Как связаны два корня","Землепашец пашет землю, рыболов ловит рыбу, полководец водит полки, золотоискатель ищет золото. Первый корень называет объект действия.","Мореход ходит по морю. Первый корень указывает на место, а не на объект."]},{"author":"Е. Бикмаев","question":"Какое русское слово вошло во многие европейские языки?","choices":["<em>двойка</em>","<em>тройка</em>","<em>пятёрка</em>","<em>семёрка</em>","<em>девятка</em>."],"key":"Б","review":["Русское слово в других языках","В названиях чисел ищи культурное значение. Тройка — в том числе традиционная упряжка из трёх лошадей.","Слово «тройка» заимствовали как название упряжки. В других языках оно часто имеет написание «troika»."]},{"author":"Н. Петрова","question":"Даны литовские слова pietūs ‘полдень / обед’, rytas ‘утро’, vakaras ‘вечер’. Названия каких сторон света от них образованы? Примечание: ū читается как долгий <em>у</em>, y читается как долгий <em>и</em>.","choices":["pietūs (запад), rytai (север), vakarai (восток)","pietūs (юг), rytai (запад), vakarai (восток)","pietūs (восток), rytai (юг), vakarai (север)","pietūs (юг), rytai (восток), vakarai (запад)","pietūs (север), rytai (запад), vakarai (юг)."],"key":"Г","review":["Стороны света по-литовски","Утром солнце восходит на востоке, вечером садится на западе. Поэтому «rytai» связано с востоком, а «vakarai» — с западом.","В Литве солнце около полудня видно на южной стороне. «Pietūs» соответствует югу. Порядок: юг, восток, запад."]},{"author":"Е. Бикмаев","question":"Дан отрывок из стихотворения Константина Батюшкова, в котором мы допустили одну пунктуационную ошибку. Какая это ошибка?\n<em>Быстро несется цветок розмаринный;\nВоды умчались — цветочка уж нет!\nВремя быстрее, чем ток сей пустынный,\nС ревом, который сквозь дебри течет!</em>","choices":["Вместо тире должно быть двоеточие.","Слово <em>уж</em> должно быть выделено запятыми с обеих сторон.","Нужна запятая после слова <em>ток</em>.","Не нужна запятая перед словом <em>чем</em>.","Не нужна запятая перед словом <em>который.</em>"],"key":"Д","review":["Запятая внутри строки","Переставь слова в обычный порядок: «чем ток сей пустынный, который с рёвом течёт сквозь дебри». В поэтическом порядке «с рёвом» вынесено вперёд.","Запятая нужна перед придаточной частью, начиная со слов «с рёвом». Между «с рёвом» и «который» ставить её не надо."]},{"author":"Б. Иомдин","question":"Лингвист подбирал примеры употребления одного просторечного слова. В каком примере нет этого слова?","choices":["<em>Здесь, по заимкам, реже случается, а в деревнях — прям выносят еду каждую ночь на улицу, за окошко.</em> (Н. Д. Телешов)","<em>Ваньчок подполз к Кареву и вынул бутыль. — Валяй прям из горлышка.</em> (С. А. Есенин)","<em>— Государь честен, бодр, — говорил Пушкин уныло и бродил глазами по лицам и плечам, — прям, того и гляди каторжников вернёт.</em> (Ю. Н. Тынянов)","<em>Никуда он не убежит… А показания может дать прям аховые.</em> (П. Н. Краснов)","<em>Они отрезы везут, кустюмы везут, мыло везут — прям как на ярмарку и снаряжались.</em> (А. И. Солженицын)"],"key":"В","review":["Часть речи слова «прям»","В отрывках про еду, бутылку, показания и ярмарку «прям» можно заменить разговорным «прямо» или «просто».","В реплике «государь честен, бодр, … прям» перечислены качества. «Прям» — краткая форма «прямой», поэтому это другое слово."]},{"author":"Л. Фёдорова","question":"В лимерике (коротком шуточном стишке) английского поэта Э. Лира в переводе Г. Кружкова мы пропустили в двух строчках одну и ту же последовательность букв:\n<em>Жил старик у подножья Везувия,\nИзучавший работы Витрувия,\nНо сгорел его том,\nИ он взялся за ___,\n___античный старик у Везувия.</em>\nКакая первая из них?","choices":["<em>д</em>","<em>к</em>","<em>л</em>","<em>н</em>","<em>р</em>."],"key":"Д","review":["Пропуск в лимерике","В предыдущей строке сгорел том. В лимерике новая строка должна заканчиваться похожим звуком, а пропущенная часть повторяется в следующей.","Подходит «ром»: после потери книги старик взялся за ром и называется «романтичным». Первая буква Р."]},{"author":"И. Рубанов","question":"Какое из четырёх устойчивых выражений, данных в ответах, означает совсем не то, что три других?","choices":["<em>между небом и землёй</em>","<em>между двух огней</em>","<em>между молотом и наковальней</em>","<em>между Сциллой и Харибдой</em>","все эти четыре выражения означают одно и то же."],"key":"А","review":["Четыре выражения с «между»","Огонь с двух сторон, молот и наковальня, Сцилла и Харибда — образы двух опасностей или сил, которые давят с разных сторон.","«Между небом и землёй» значит в подвешенном, неопределённом положении. Оно описывает другую ситуацию."]},{"author":"Б. Иомдин","question":"К какому существительному нельзя приписать <em>-альный</em> и получить прилагательное?","choices":["<em>тон</em>","<em>фронт</em>","<em>экстрим</em>","<em>спектр</em>","<em>обруч</em>."],"key":"В","review":["Суффикс прилагательного","К «тон», «фронт», «спектр» и «обруч» можно прибавить «-альный». Получаются «тональный», «фронтальный», «спектральный», «обручальный».","От «экстрим» прямым прибавлением получилось бы «экстримальный». Нормативное «экстремальный» имеет в основе Е, поэтому такой способ здесь не работает."]},{"author":"С. Дьяченко, И. Иткин и С. Сай","question":"В каком из этих слов русского литературного языка, возможно, пропущена не та буква, что в остальных?","choices":["<em>прям_ком</em>","<em>цел_ком</em>","<em>бос_ком</em>","<em>ёж_ком</em>","во всех этих словах точно пропущена одна и та же буква."],"key":"В","review":["Гласная в пропуске","В «прямиком», «целиком» и «ёжиком» подходит И. «Босиком» тоже можно написать с И, если имеется в виду «босой ногой».","Но есть существительное «босяк» и его форма «босяком». Если употребить эту форму, в том же пропуске будет Я."]},{"author":"Б. Иомдин","question":"В этом четверостишии Иосифа Бродского мы не привели три последних коротких слова:\n<em>Я слышу не то, что ты мне говоришь, а голос.\nЯ вижу не то, во что ты одета, а ровный снег.\nИ это не комната, где мы сидим, но полюс;\nплюс наши следы ведут от него, ___ ___ ___.</em>\nК каким частям речи относятся эти слова?","choices":["союз, частица, предлог","частица, предлог, союз","союз, местоимение, частица","местоимение, частица, союз","местоимение, союз, предлог."],"key":"А","review":["Конец строки Бродского","Следы «ведут от него». Для смысла ожидается противопоставление: следы идут от полюса, а не в его сторону. Последнее слово должно рифмоваться со «снег».","Получается «а не к». «А» — союз, «не» — отрицательная частица, «к» — предлог."]},{"author":"А. Пиперски и И. Рубанов","question":"Двузначные числа, которые чаще всего встречаются в русских текстах на месте пропуска в сочетании <em>за … суток</em>, — это 10, 45 и 30. А какое из нижеприведённых двузначных чисел встречается на этом месте значительно реже четырёх других?","choices":["14","24","27","35","60."],"key":"Б","review":["Число перед «суток»","«Сутки» употребляются только во множественном числе. После 14, 27, 35 и 60 возможен родительный множественного «суток».","После 24 обычно понадобилась бы форма, которая у «суток» в этой конструкции не подходит. Вместо «за двадцать четыре суток» говорят «за двадцать четыре дня»."]},{"author":"С. Сай","question":"Во всех этих словах, кроме одного, можно заменить одну букву другой так, чтобы получилась форма глагола несовершенного вида. А в каком слове это не получится?","choices":["<em>срубил</em>","<em>слизал</em>","<em>снял</em>","<em>списал</em>","<em>стёр</em>."],"key":"Д","review":["Замени одну букву","Можно получить «грубил», «слезал», «снул» и «спасал» из первых четырёх слов. Это формы несовершенного вида, в том числе «снул» от «снуть».","Из «стёр» похожая замена даёт, например, «втёр», но он тоже совершенного вида. Подходящей формы несовершенного вида одной заменой не получается."]},{"author":"И. Иткин","question":"С какого из этих сочетаний букв может начинаться и исконно русское, и заимствованное слово?","choices":["<em>асс</em>...","<em>жже</em>...","<em>щуч</em>...","<em>поэ</em>...","<em>фло</em>... ."],"key":"Г","review":["Исконное и заимствованное","Ищи одинаковые начальные буквы у слов разного происхождения. Например, «поэт» — заимствованное слово.","«Поэтому» образовалось в русском из «по этому». У обоих слов начало «поэ»."]},{"author":"Б. Иомдин","question":"Устаревший глагол <em>скать</em> сейчас не употребляется, но в современном языке остались образованные от него существительные. А что он означал?","choices":["‘говорить, спрашивать’","‘прыгать, подпрыгивать’","‘крутить, катать’","‘съезжать, сваливаться’","‘искать, высматривать’."],"key":"В","review":["Слово, оставшееся в предметах","Подумай о слове «скалка». Ею раскатывают тесто. В слове сохранилось старое название действия.","Глагол «скать» означал «крутить, катать». Это тот смысл, который помогает понять название скалки."]},{"author":"Е. Муравенко","question":"Даны пары глаголов, различающихся в 1-м лице единственного числа только ударением:\n1) <em>ме́чу — мечу́</em>, 2) <em>пла́чу — плачу́</em>, 3) <em>су́жу — сужу́</em>. В каких парах оба глагола относятся к одному и тому же спряжению?","choices":["только в 1-й","только во 2-й","только в 3-й","ни в каких","во всех."],"key":"В","review":["Ударение и спряжение","«Ме́чу» от «метить» и «мечу́» от «метать» дают «метишь» и «мечешь». «Пла́чу» и «плачу́» дают «плачешь» и «платишь». В первых двух парах личные окончания разных спряжений.","«Су́жу» от «сузить» даёт «сузишь», «сужу́» от «судить» — «судишь». Оба глагола третьей пары относятся ко второму спряжению."]},{"author":"С. Сай","question":"«Вторым предложным» иногда называют такую форму предложного падежа, которая может использоваться после предлогов <em>в</em> или <em>на</em> и при этом отличается от той формы того же существительного, которая используется после предлога <em>о</em>, ср. <em>в лесу</em>, но <em>о лесе</em>. У какого из следующих слов есть два варианта предложного падежа?","choices":["<em>время</em>","<em>парк</em>","<em>пыль</em>","<em>пятница</em>","<em>соль</em>."],"key":"В","review":["Два предложных падежа","Сравни «о парке — в парке» и «о соли — в соли». Особая форма после «в» у этих слов не появляется.","У слова «пыль» ударения в «о пы́ли» и «в пыли́» различаются. Вторая форма употребляется с местным значением."]}], {"year":2020,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2020-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
